import * as React from "react";
import { cx } from "./cx";

export interface InputGroupProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Place the addon after the field. */
  end?: boolean;
}

/** Addon and field share one hairline. */
export function InputGroup({ end, className, ...props }: InputGroupProps) {
  return <div className={cx("rs-input-group", end && "rs-input-group-end", className)} {...props} />;
}

export function InputAddon({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={cx("rs-input-addon", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Input group: addon and field share one hairline.
   Outer radius is the standalone input; innerRadius with no pad. ── */
.rs-input-group{
  --rs-out:var(--radius-sm);
  --rs-gap:0px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  display:flex;
  align-items:stretch;
  box-sizing:border-box;
  width:100%;
  height:var(--control-h);
  border:1px solid var(--divider);
  border-radius:var(--rs-out);
  background:var(--bg);
  overflow:hidden
}
.rs-input-group:focus-within{border-color:var(--accent)}
.rs-input-addon{display:flex;align-items:center;padding:0 10px;font-size:13px;font-weight:500;letter-spacing:-.01em;color:var(--text-secondary);background:var(--table-alt);white-space:nowrap}
.rs-input-group > * + *{border-inline-start:1px solid var(--divider)}
.rs-input-group .rs-input{border:none;border-radius:var(--rs-in);flex:1;min-width:0;height:auto;line-height:calc(var(--control-h) - 2px)}
.rs-input-group .rs-input:focus{outline:none}
.rs-input-group-end .rs-input-addon{border-inline-start:1px solid var(--divider)}
